import { Effect, Schema } from "effect"

const CommandEntry = Schema.Struct({
  name: Schema.String,
  aliases: Schema.Array(Schema.String)
})

const CommandManifest = Schema.Struct({
  formatVersion: Schema.Literal(1),
  commandCount: Schema.Number.check(Schema.isInt()),
  commands: Schema.Array(CommandEntry)
})

const builtInCommands = [
  { name: "initialize", aliases: ["init"] },
  { name: "inspect", aliases: ["info"] },
  { name: "synchronize", aliases: ["sync"] }
] as const

export const encodeBuiltInCommandManifest = () =>
  Effect.gen(function*() {
    const commands = builtInCommands.map((command) => ({
      name: command.name,
      aliases: [...command.aliases]
    }))

    const manifest = {
      formatVersion: 1 as const,
      commandCount: commands.length,
      commands
    }

    return yield* Schema.encodeEffect(CommandManifest)(manifest).pipe(Effect.orDie)
  })
